&lt;/li&gt;
&lt;li class=&quot;public-DraftStyleDefault-unorderedListItem public-DraftStyleDefault-depth0 public-DraftStyleDefault-listLTR&quot; data-block=&quot;true&quot; data-editor=&quot;fhg0m&quot; data-offset-key=&quot;7917f-0-0&quot;&gt;
&lt;div class=&quot;public-DraftStyleDefault-block public-DraftStyleDefault-ltr&quot; data-offset-key=&quot;7917f-0-0&quot;&gt;&lt;span data-offset-key=&quot;7917f-0-0&quot;&gt;&lt;span data-text=&quot;true&quot;&gt;Help drive day-to-day execution of programs by following up on action items, managing timelines, and identifying risks when needed&lt;/span&gt;&lt;/span&gt;&lt;/div&gt;
