&lt;div class=&quot;public-DraftStyleDefault-block public-DraftStyleDefault-ltr&quot; data-offset-key=&quot;8e6e7-0-0&quot;&gt;&lt;span id=&quot;popover-trigger-:rng:&quot; class=&quot;chakra-text css-1h4n5cs&quot;&gt;&lt;span data-offset-key=&quot;8e6e7-0-0&quot;&gt;&lt;span data-text=&quot;true&quot;&gt;Familiarity&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;span data-offset-key=&quot;8e6e7-1-0&quot;&gt;&lt;span data-text=&quot;true&quot;&gt; with project management tools (e.g., Workfront or similar platforms)&lt;/span&gt;&lt;/span&gt;&lt;/div&gt;
