&lt;p lang=&quot;es&quot; style=&quot;margin: 0in; font-family: Arial; font-size: 11pt; line-height: 1.2;&quot;&gt;&amp;nbsp;&lt;/p&gt;
&lt;p lang=&quot;es&quot; style=&quot;margin-top: 0pt; margin-bottom: 8pt; font-family: Arial; font-size: 11pt; color: rgb(47, 47, 47); line-height: 1.2;&quot;&gt;&lt;span style=&quot;font-weight: bold; font-family: helvetica, arial, sans-serif; font-size: 18pt;&quot;&gt;Why You&#39;ll Love it Here&lt;/span&gt;&lt;/p&gt;
